"""Tests for tasks_api.queries — apply_query, TaskQuery, TaskPage."""

from datetime import datetime, timedelta, timezone

import pytest

from tasks_api.models import Tag, Task, TaskPriority, TaskStatus
from tasks_api.queries import TaskPage, TaskQuery, TaskQueryError, apply_query


class TestTaskQueryValidation:
    def test_invalid_sort_field(self):
        with pytest.raises(TaskQueryError, match="sort must be one of"):
            TaskQuery(sort="invalid")

    def test_limit_zero(self):
        with pytest.raises(TaskQueryError, match="limit must be"):
            TaskQuery(limit=0)

    def test_limit_over_100(self):
        with pytest.raises(TaskQueryError, match="limit must be"):
            TaskQuery(limit=101)

    def test_negative_offset(self):
        with pytest.raises(TaskQueryError, match="offset must be"):
            TaskQuery(offset=-1)

    def test_invalid_tag_raises(self):
        with pytest.raises((TaskQueryError, ValueError)):
            TaskQuery(tag="bad tag!")

    def test_tag_is_normalized(self):
        q = TaskQuery(tag="  Hello  ")
        assert q.tag == "hello"

    def test_whitespace_search_becomes_none(self):
        q = TaskQuery(search="   ")
        assert q.search is None


class TestApplyQueryFilters:
    def test_filter_by_status_pending(self, sample_tasks, now):
        page = apply_query(sample_tasks, TaskQuery(status=TaskStatus.PENDING), now)
        assert all(t.status == TaskStatus.PENDING for t in page.items)
        assert page.total == 4

    def test_filter_by_status_done(self, sample_tasks, now):
        page = apply_query(sample_tasks, TaskQuery(status=TaskStatus.DONE), now)
        assert page.total == 1
        assert page.items[0].id == 2

    def test_filter_by_tag(self, sample_tasks, now):
        page = apply_query(sample_tasks, TaskQuery(tag="shopping"), now)
        assert page.total == 2
        assert {t.id for t in page.items} == {1, 5}

    def test_filter_by_search(self, sample_tasks, now):
        page = apply_query(sample_tasks, TaskQuery(search="buy"), now)
        assert page.total == 2
        assert {t.id for t in page.items} == {1, 5}

    def test_search_case_insensitive(self, sample_tasks, now):
        page = apply_query(sample_tasks, TaskQuery(search="REPORT"), now)
        assert page.total == 1

    def test_filter_overdue_true(self, sample_tasks, now):
        page = apply_query(sample_tasks, TaskQuery(overdue=True), now)
        # Tasks 1 and 5 are overdue (pending + past due_at)
        assert page.total == 2
        assert {t.id for t in page.items} == {1, 5}

    def test_filter_overdue_false(self, sample_tasks, now):
        page = apply_query(sample_tasks, TaskQuery(overdue=False), now)
        # Tasks 2 (done), 3 (future due), 4 (no due) are not overdue
        assert page.total == 3

    def test_combined_filters(self, sample_tasks, now):
        page = apply_query(
            sample_tasks,
            TaskQuery(status=TaskStatus.PENDING, tag="shopping", search="gift"),
            now,
        )
        assert page.total == 1
        assert page.items[0].id == 5


class TestApplyQuerySort:
    def test_sort_by_created_at_asc(self, sample_tasks, now):
        page = apply_query(sample_tasks, TaskQuery(sort="created_at", limit=100), now)
        created_ats = [t.created_at for t in page.items]
        assert created_ats == sorted(created_ats)

    def test_sort_by_created_at_desc(self, sample_tasks, now):
        page = apply_query(sample_tasks, TaskQuery(sort="created_at", descending=True, limit=100), now)
        created_ats = [t.created_at for t in page.items]
        assert created_ats == sorted(created_ats, reverse=True)

    def test_sort_by_priority(self, sample_tasks, now):
        page = apply_query(sample_tasks, TaskQuery(sort="priority", limit=100), now)
        priorities = [TaskPriority.order_key(t.priority) for t in page.items]
        assert priorities == sorted(priorities)

    def test_sort_by_title(self, sample_tasks, now):
        page = apply_query(sample_tasks, TaskQuery(sort="title", limit=100), now)
        titles = [t.title.lower() for t in page.items]
        assert titles == sorted(titles)

    def test_sort_by_due_at_none_last(self, sample_tasks, now):
        page = apply_query(sample_tasks, TaskQuery(sort="due_at", limit=100), now)
        # Task 4 has no due_at, should be last
        assert page.items[-1].id == 4


class TestApplyQueryPagination:
    def test_limit(self, sample_tasks, now):
        page = apply_query(sample_tasks, TaskQuery(limit=2), now)
        assert len(page.items) == 2
        assert page.total == 5
        assert page.has_more is True

    def test_offset(self, sample_tasks, now):
        page = apply_query(sample_tasks, TaskQuery(limit=2, offset=3), now)
        assert len(page.items) == 2
        assert page.offset == 3
        assert page.has_more is False

    def test_offset_beyond(self, sample_tasks, now):
        page = apply_query(sample_tasks, TaskQuery(limit=10, offset=100), now)
        assert len(page.items) == 0
        assert page.total == 5
        assert page.has_more is False

    def test_has_more_false_exact_boundary(self, sample_tasks, now):
        page = apply_query(sample_tasks, TaskQuery(limit=5), now)
        assert page.has_more is False


class TestTaskPage:
    def test_has_more_true(self):
        page = TaskPage(items=[Task(id=1, title="x")], total=5, limit=1, offset=0)
        assert page.has_more is True

    def test_has_more_false(self):
        page = TaskPage(items=[Task(id=1, title="x")], total=1, limit=10, offset=0)
        assert page.has_more is False

